// Convierte el update de Telegram (mensaje o botón) en un objeto simple con la ruta a seguir.
const u = $input.first().json;
const IGNORE = [{ json: { route: 'ignore' } }];
const MARK = /\[#(p?)(\d+) (next|wait|first|wnow|padd)\]/;

if (u.callback_query) {
  const q = u.callback_query;
  if (!q.message || !q.message.chat || q.message.chat.type !== 'private') return IGNORE;
  const d = q.data || '';
  const o = { kind: 'callback', user_id: q.from.id, chat_id: q.message.chat.id,
              message_id: q.message.message_id, callback_id: q.id, data: d };
  const simple = { home: 'home', capture: 'capture_hint', inbox: 'inbox', next: 'next',
                   projects: 'projects', future: 'future', waiting: 'waiting',
                   review: 'review', review_done: 'review_done' };
  const c = d.match(/^c:(next|wait|some|ref|trash|proj):(\d+)$/);
  const lp = d.match(/^lp:([nwsp]):(\d{1,3})$/);                       // otra página de una lista
  const v = d.match(/^v:(\d+):([nws])$/);                              // abrir una tarea
  const a = d.match(/^a:(done|snz1|snz3|snz7|trash|act|wait|undo|unsnz|tosome|tonext):(\d+):([nws])$/);
  const pv = d.match(/^pv:(\d+)$/);                                   // abrir un proyecto
  const pa = d.match(/^pa:(add|done|donec|donet|drop|dropt|some|reopen):(\d+)$/);
  if (c) { o.route = 'clarify'; o.action = c[1]; o.task_id = Number(c[2]); }
  else if (lp) { o.route = { n: 'next', w: 'waiting', s: 'future', p: 'projects' }[lp[1]]; o.page = Number(lp[2]); }
  else if (v) { o.route = 'view'; o.task_id = Number(v[1]); o.from = v[2]; }
  else if (a) { o.route = 'act'; o.action = a[1]; o.task_id = Number(a[2]); o.from = a[3]; }
  else if (pv) { o.route = 'pview'; o.project_id = Number(pv[1]); }
  else if (pa) { o.route = 'pact'; o.action = pa[1]; o.project_id = Number(pa[2]); }
  else if (simple[d]) { o.route = simple[d]; }
  else { o.route = 'ignore'; }
  return [{ json: o }];
}

if (u.message) {
  const m = u.message;
  if (!m.from || m.from.is_bot || !m.chat || m.chat.type !== 'private') return IGNORE;
  const o = { kind: 'message', user_id: m.from.id, chat_id: m.chat.id,
              message_id: m.message_id, text: m.text || '' };
  if (!m.text) { o.route = 'unsupported'; return [{ json: o }]; }
  const rt = m.reply_to_message && m.reply_to_message.from && m.reply_to_message.from.is_bot
    && m.reply_to_message.text;
  const mk = rt && rt.match(MARK);
  if (mk) {
    o.route = 'reply'; o.step = mk[3];
    if (mk[1]) o.project_id = Number(mk[2]); else o.task_id = Number(mk[2]);
  } else if (m.text.startsWith('/')) {
    o.route = 'menu';
  } else {
    o.route = 'capture';   // cualquier texto suelto se captura: capturar no debe tener fricción
  }
  return [{ json: o }];
}
return IGNORE;

const N = () => $('Normalizar').first().json;
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const one = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const label = (t) => clip(one(t.title || t.raw_text), 80);
const unwrap = (r) => (!r || r.error || r.statusCode === undefined)
  ? { ok: false, status: 0, body: null }
  : { ok: r.statusCode >= 200 && r.statusCode < 300, status: r.statusCode, body: r.body !== undefined ? r.body : r.data };
const detail = (r) => {
  const d = r.body && r.body.detail;
  if (typeof d === 'string') return d;
  if (Array.isArray(d)) return d.map((x) => x.msg).join('; ');
  return r.status ? 'error ' + r.status : 'no pude conectar con el servidor GTD';
};
const mode = () => (N().kind === 'callback' ? 'edit' : 'send');
// El nodo Telegram de n8n fuerza parse_mode en los envíos (Markdown si no se indica otro). Para que
// el texto del usuario salga siempre tal cual, los nodos TG usan HTML y aquí se escapa & < >
// una sola vez: lo que ves en Telegram es texto plano.
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fit = (text) => {   // Telegram admite 4096 caracteres ya escapados
  let t = clip(text, 3500); let e = esc(t);
  while (e.length > 4090) { t = clip(t, Math.floor(t.length * 0.8)); e = esc(t); }
  return e;
};
const show = (screen, text, extra = {}) => [{ json: Object.assign(
  { screen, text: fit(text), chat_id: N().chat_id, message_id: N().message_id }, extra) }];
// 403 = usuario fuera de la allowlist: no se responde nada. 401 = la API key del flujo está mal.
const gate = (r) => {
  if (r.status === 403) return [];
  if (r.status === 401) return show(mode() + '-list', '⚠️ La API key de este flujo no es válida.');
  return null;
};
const whenOf = (iso) => {
  if (!iso) return '';
  const late = new Date(iso) < new Date();
  return ' — ' + (late ? '⚠️ venció ' : 'vence ') + Number(iso.slice(8, 10)) + '/' + Number(iso.slice(5, 7)) + ' ' + iso.slice(11, 16);
};
const days = (n) => (n === 0 ? 'hoy' : n === 1 ? '1 día' : n + ' días');
const PAGE = 5;
// Reparte una lista en páginas de 5 y prepara los datos de los botones (un número por tarea y navegación).
const paged = (items, kind) => {
  const pages = Math.max(1, Math.ceil(items.length / PAGE));
  const page = Math.min(Math.max(Number(N().page) || 0, 0), pages - 1);
  const slice = items.slice(page * PAGE, page * PAGE + PAGE);
  return { slice, page, pages, base: page * PAGE, screen: 'edit-pick-' + slice.length + (pages > 1 ? '-nav' : ''),
    extra: { kind, ids: slice.map((t) => t.id), nums: slice.map((t, i) => String(page * PAGE + i + 1)), label: (page + 1) + '/' + pages,
             prev: page > 0 ? 'lp:' + kind + ':' + (page - 1) : 'noop',
             nxt: page < pages - 1 ? 'lp:' + kind + ':' + (page + 1) : 'noop' } };
};
const pageTag = (p) => (p.pages > 1 ? ' — pág. ' + (p.page + 1) + '/' + p.pages : '');
const dmy = (iso) => Number(iso.slice(8, 10)) + '/' + Number(iso.slice(5, 7));
const splitContext = (text) => {
  // "Llamar a Ana @telefono" -> título "Llamar a Ana", contexto "@telefono"
  const re = /(^|\s)(@[\p{L}\p{N}_-]{1,40})(?=\s|$)/gu;
  let last = null; let m;
  while ((m = re.exec(text)) !== null) last = m;
  if (!last) return { title: one(text), context: null };
  const title = one(text.slice(0, last.index) + ' ' + text.slice(last.index + last[0].length));
  return { title, context: last[2] };
};

const r = unwrap($input.first().json);
const g = gate(r); if (g) return g;
if (!r.ok) return show(mode() + '-list', '⚠️ No pude leer tus datos: ' + detail(r));
const s = r.body.snapshot;
const lines = [
  '🏠 GTD — ¿qué quieres hacer?', '',
  '📥 Inbox: ' + s.inbox + '    ▶️ Acciones: ' + s.next,
  '⏳ Esperando: ' + s.waiting + '    🌱 Algún día: ' + s.someday,
];
if (s.stalled_projects) lines.push('🧩 Proyectos sin siguiente paso: ' + s.stalled_projects);
if (s.overdue) lines.push('⚠️ Vencidas: ' + s.overdue);
lines.push('', '✍️ Escríbeme cualquier cosa y la capturo al inbox.');
return show(mode() + '-menu', lines.join('\n'));

