const show = (screen, text, extra = {}) => [{ json: Object.assign(
  { screen, text: fit(text), chat_id: N().chat_id, message_id: N().message_id }, extra) }];
// 403 = usuario fuera de la allowlist: no se responde nada. 401 = la API key del flujo está mal.
const gate = (r) => {
  if (r.status === 403) return [];
  if (r.status === 401) return show(mode() + '-list', '⚠️ La API key de este flujo no es válida.');
  return null;
};
const whenOf = (iso) => {
  if (!iso) return '';
  const late = new Date(iso) < new Date();
  return ' — ' + (late ? '⚠️ venció ' : 'vence ') + Number(iso.slice(8, 10)) + '/' + Number(iso.slice(5, 7)) + ' ' + iso.slice(11, 16);
};
const days = (n) => (n === 0 ? 'hoy' : n === 1 ? '1 día' : n + ' días');
const PAGE = 5;
// Reparte una lista en páginas de 5 y prepara los datos de los botones (un número por tarea y navegación).
const paged = (items, kind) => {
  const pages = Math.max(1, Math.ceil(items.length / PAGE));
  const page = Math.min(Math.max(Number(N().page) || 0, 0), pages - 1);
  const slice = items.slice(page * PAGE, page * PAGE + PAGE);
  return { slice, page, pages, base: page * PAGE, screen: 'edit-pick-' + slice.length + (pages > 1 ? '-nav' : ''),
    extra: { kind, ids: slice.map((t) => t.id), nums: slice.map((t, i) => String(page * PAGE + i + 1)), label: (page + 1) + '/' + pages,
             prev: page > 0 ? 'lp:' + kind + ':' + (page - 1) : 'noop',
             nxt: page < pages - 1 ? 'lp:' + kind + ':' + (page + 1) : 'noop' } };
};
const pageTag = (p) => (p.pages > 1 ? ' — pág. ' + (p.page + 1) + '/' + p.pages : '');
const dmy = (iso) => Number(iso.slice(8, 10)) + '/' + Number(iso.slice(5, 7));
const splitContext = (text) => {
  // "Llamar a Ana @telefono" -> título "Llamar a Ana", contexto "@telefono"
  const re = /(^|\s)(@[\p{L}\p{N}_-]{1,40})(?=\s|$)/gu;
  let last = null; let m;
  while ((m = re.exec(text)) !== null) last = m;
  if (!last) return { title: one(text), context: null };
  const title = one(text.slice(0, last.index) + ' ' + text.slice(last.index + last[0].length));
  return { title, context: last[2] };
};

